local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'
local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local UITeamMembersNode = "Game.UI.FightTeam.UITeamMembersNode.UITeamMembersNode"
local CommonPlayerHeadNode = "Game.Behaviours.CommonPlayerHeadNode"
local towerQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TowerQuestComponent)

---@class UIClimbTowerVideoCellNode
---@field CardPar                       	UnityEngine.RectTransform                            
local UIClimbTowerVideoCellNode = Class("UIClimbTowerVideoCellNode")
function UIClimbTowerVideoCellNode:__init() 
    self._data = nil
    self._commonPlayerHeadNodeScr = nil
end

function UIClimbTowerVideoCellNode:__delete()
    self._data = nil
    self._commonPlayerHeadNodeScr = nil
end

function UIClimbTowerVideoCellNode:Awake()
    if not self._commonPlayerHeadNodeScr then
        self._commonPlayerHeadNodeScr = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, CommonPlayerHeadNode)
    end
end

function UIClimbTowerVideoCellNode:Start()
end

function UIClimbTowerVideoCellNode:Refresh(data, cardCb)
    self._data = data
    if not self._data then
        KTool.SetActive(self.controller.gameObject, false)
        return
    end
    --没有这个记录 隐藏
    if table.count(checkTable(self._data.team)) <= 0 then
        KTool.SetActive(self.controller.gameObject, false)
        return
    end

    self:FillSelf()
end

function UIClimbTowerVideoCellNode:FillSelf()
    local scr = CfUtils.GetLuaScr(self.UITeamMembersNode, UITeamMembersNode)
    if scr then
        scr:Refresh(self._data.team[1].cardInfo, false, 0.7)
    end
    CfUtils.FillText(self.Text2, checkNumber(self._data.team[1].combatValue))

    local roleInfo = self._data
    if roleInfo then
        CfUtils.FillText(self.TxtLV, checkNumber(roleInfo.level))
        CfUtils.FillText(self.TxtName, roleInfo.name)
    end

    if self._commonPlayerHeadNodeScr then
        self._commonPlayerHeadNodeScr:FreshAvatarFrame(self._data.avatar, self._data.avatarFrame)
    end

    SetButtonAction(self.ButPlay, function()
        FightPreWarMgr:GetInstance():FightReplay(self._data.battleData)
    end)

    KTool.SetActive(self.controller.gameObject, true)

    local go = self.controller.gameObject.transform:Find("BtnReport")
    if go then
        CfUtils.SetActive(go, true)
        SetButtonAction(go, Bind(self, self.OnBtnReport))
    end
end

--举报
function UIClimbTowerVideoCellNode:OnBtnReport()
    if not self._data then
        return
    elseif self._isReport then
        return
    end
    local remainNum = towerQuestComponent:GetRemainReportNum()

    if remainNum <= 0 then
        GameUtils.Toast(localize("今日举报次数已用完"))
        return
    end

    self._isReport = true
    local maxNum = QuestConfMgr:GetInstance():GetClimbTowerMaxReportNum()
    GameUtils.SecondConfirm(localize("是否举报外挂录像?"), function()
        towerQuestComponent:ClimbingTowerReportVideoReq(self._data.videoId, function()
            self._isReport = false
            GameUtils.Toast(localize("举报成功"))
        end)
    end, function()
        self._isReport = false
    end, localize("今日剩余举报次数_num1_/_num2_", {_num1_ = remainNum, _num2_ = maxNum}))
end

function UIClimbTowerVideoCellNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIClimbTowerVideoCellNode
